import numpy as np

def solve(m, ecc, E0, mode='halley', fb='reflect', max_iter=30, tol=1e-13):
    lo, hi = m.copy(), m + ecc
    flo = lo - ecc*np.sin(lo) - m
    E = E0.copy()
    for it in range(1, max_iter+1):
        f = E - ecc*np.sin(E) - m
        fp = 1 - ecc*np.cos(E)
        if mode == 'halley':
            den = 2*fp**2 - f*ecc*np.sin(E)
            cand = E - 2*f*fp/np.where(np.abs(den)<1e-300,1e-300,den)
        else:
            cand = E - f/fp
        bad = ~((cand > lo) & (cand < hi))
        if fb == 'clip05':
            alt = np.clip(cand, lo+0.05*(hi-lo), hi-0.05*(hi-lo))
        elif fb == 'reflect':
            alt = 0.5*(E + np.clip(cand, lo, hi))
        else:
            alt = 0.5*(lo+hi)
        En = np.where(bad, alt, cand)
        fn = En - ecc*np.sin(En) - m
        left = np.sign(flo)*np.sign(fn) <= 0
        hi = np.where(left, En, hi); lo = np.where(left, lo, En); flo = np.where(left, flo, fn)
        if np.all(np.abs(En-E) < tol):
            return it
        E = En
    return max_iter

for ecc in [0.9, 0.99]:
    m = np.linspace(0, np.pi, 3001)
    starts = {
     'conway': m + 0.85*ecc*np.sign(np.sin(m)),
     'vallado': m + ecc*np.sin(m)/(1 - np.sin(m+ecc) + np.sin(m)),
    }
    print('--- e =', ecc)
    for name, E0 in starts.items():
        for mode in ['halley','newton']:
            for fb in ['reflect','clip05','mid']:
                counts = np.array([solve(m[i:i+1], ecc, E0[i:i+1], mode, fb) for i in range(len(m))])
                idx = counts.argmax()
                print(f'{name:8s} {mode:6s} {fb:8s} max {counts.max():2d} at m={m[idx]:.4f} mean {counts.mean():.2f}')
EOF")
